{"script":"() => {
  // Find all elements that might be the unicode character images
  const img = document.querySelector('[id*="subpod"] img, .pod img, img[alt*="U+"]');
  if (img) return img.alt;
  // Search for all images with alt text containing U+
  const allImgs = document.querySelectorAll('img');
  const results = [];
  allImgs.forEach(i => {
    if (i.alt && i.alt.includes('U+')) {
      results.push(i.alt.substring(0, 500));
    }
  });
  return results;
}"}

